parameters.jsCode:
// 解析DeepSeek的响应
const response = $input.first().json;
let aiResponse = '';
let needToolCall = false;
let toolInfo = null;

try {
  if (response.choices && response.choices[0] && response.choices[0].message) {
    aiResponse = response.choices[0].message.content;

    // 尝试解析是否有工具调用
    try {
      // 查找JSON格式的工具调用
      const jsonMatch = aiResponse.match(/\{[\s\S]*"action"[\s\S]*"call_tool"[\s\S]*\}/);
      if (jsonMatch) {
        const toolCall = JSON.parse(jsonMatch[0]);
        if (toolCall.action === 'call_tool') {
          needToolCall = true;
          toolInfo = {
            tool_name: toolCall.tool,
            parameters: toolCall.params || {}
          };
        }
      }
    } catch (e) {
      // 不是工具调用，继续处理为普通响应
    }
  }
} catch (e) {
  aiResponse = '抱歉，处理您的请求时出现了问题。';
}

return {
  json: {
    needToolCall,
    toolInfo,
    aiResponse,
    originalMessage: $('Webhook').first().json.body.message
  }
};

const mcpResult = $input.first().json;
let reply = '';

try {
    console.log('MCP Result:', JSON.stringify(mcpResult));

    if (mcpResult && mcpResult.success) {
        const data = mcpResult.data;
        const toolName = mcpResult.tool;

        // 根据不同工具处理不同数据
        if (toolName === 'get_all_categories') {
            // 分类列表是字符串数组
            if (Array.isArray(data) && data.length > 0) {
                reply = '📂 书店目前有以下分类：\n' + data.map(cat => `• ${cat}`).join('\n');
            } else {
                reply = '暂无分类信息。';
            }
        } 
        else if (Array.isArray(data)) {
            // 书籍列表
            if (data.length > 0) {
                // 检查是否是书籍对象
                if (data[0].title) {
                    reply = '为您找到以下书籍：\n' + data.map(book => 
                        `📚 《${book.title}》- ${book.author} - ¥${book.price}`
                    ).join('\n');
                } else {
                    // 可能是其他类型的数组
                    reply = data.join('\n');
                }
            } else {
                reply = '抱歉，没有找到相关内容。';
            }
        } 
        else if (data && data.title) {
            // 单本书详情
            reply = `📖 《${data.title}》\n作者：${data.author}\n价格：¥${data.price}\n分类：${data.category || '未分类'}\n简介：${data.description || '暂无简介'}`;
        }
        else if (data === null) {
            reply = '没有找到相关信息。';
        }
        else {
            // 其他情况，直接显示
            reply = typeof data === 'string' ? data : JSON.stringify(data, null, 2);
        }
    } else {
        reply = '查询时出现问题：' + (mcpResult?.error || '未知错误');
    }
} catch (e) {
    reply = '处理结果时出错：' + e.message;
}

return {
    json: {
        reply,
        success: true
    }
};

return {
  json: {
    reply: $('Parse Response').first().json.aiResponse,
    success: true
  }
};
